export function GET(request) {
  const square = new URL(request.url).searchParams.get("m");
  return new Response(Buffer.from(square ? SQUARE_BASE64 : ROUND_BASE64, "base64"), {
    headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400" },
  });
}
